<?php use App\UI\UI as U; ?>
<?= U::heading('Find stations', 'Fresh refills from local water stations in Hamtic, Antique.') ?>
<section class="panel p-5 md:p-6"><div class="grid gap-4 md:grid-cols-[1fr_220px] mb-6"><?= U::field('Search stations', 'station_search', '', 'search', ['placeholder' => 'Station, barangay or area', 'data-search' => 'station-list']) ?><?= U::select('Availability', 'availability', ['all' => 'All stations', 'open' => 'Open now', 'closed' => 'Currently unavailable'], 'all', ['data-filter-target' => 'station-list']) ?></div><div id="station-list" class="space-y-4"><?php foreach ($data['sample']['stations'] as $i => $s): ?><article data-search-row data-filter-value="<?= $i === 0 ? 'open' : 'closed' ?>" class="flex flex-wrap items-center gap-5 rounded-xl border border-line p-5"><?= U::productImage('h-28 w-28 rounded-xl bg-foam object-contain') ?><div class="flex-1"><h2 class="text-xl font-bold"><?= U::e($s['name']) ?></h2><p class="muted mt-1">Brgy. <?= U::e($s['area']) ?>, Hamtic, Antique</p><div class="mt-3"><?= U::badge($s['status'], $s['tone']) ?></div><p class="muted mt-3">Refills from <?= U::money(\App\UI\Products::get('small')['price']) ?> per container &middot; Bottled water from <?= U::money(\App\UI\Products::get('bottle350')['price']) ?> per box</p></div><?= U::btn('View station', '/customer/station?station='.$s['id'], $i === 0 ? 'primary' : 'secondary', 'arrow-right') ?></article><?php endforeach; ?></div><p data-empty hidden class="p-8 text-center muted">No stations match your search. Try another barangay.</p></section>
